func TestIdemConcurrent(t *testing.T) {
	const n = 32
	ctx := context.Background()
	f := &idemConcurrentWallets{wallets: map[string]domain.Wallet{
		"w-1": {ID: "w-1", WalletType: "standard", Balance: 0, Status: domain.StatusEnable},
	}}
	s := &Server{Svc: &service.Service{Wallets: f, Core: idemConcurrentCore{}}}

	errs := make([]error, n)
	var start, done sync.WaitGroup
	start.Add(1)
	for i := 0; i < n; i++ {
		done.Add(1)
		go func(i int) {
			defer done.Done()
			start.Wait()
			errs[i] = s.Deposit(ctx, "w-1", 100, "trk-1")
		}(i)
	}
	start.Done()
	done.Wait()

	if f.mostAtOnce < 2 {
		t.Fatal("no two deposits were between their balance read and their balance write at the same time — raise n; this run proved nothing")
	}
	succeeded := 0
	for _, err := range errs {
		if err == nil {
			succeeded++
		}
	}
	t.Logf("%d of %d deposits reported success; up to %d were between read and write at once", succeeded, n, f.mostAtOnce)

	rows := 0
	for _, tx := range f.inserted {
		if tx.TrackingNumber == "trk-1" {
			rows++
		}
	}
	if rows != 1 {
		t.Errorf("%d history rows carry tracking number trk-1 after %d simultaneous deliveries, want 1: the key is never checked (service/transfer.go:62)", rows, n)
	}
	if f.balanceWrites != 1 {
		t.Errorf("%d balance writes for one deposit delivered %d times at once, want 1", f.balanceWrites, n)
	}
	if got := f.wallets["w-1"].Balance; got != 100 {
		t.Errorf("balance = %d, want 100: one deposit of 100, delivered %d times at once; the %d history rows say %d was credited, so the balance and its history also disagree", got, n, rows, 100*rows)
	}
}
